{
  "aktywnosci": [
    {
      "tytul": "Kłębuszek dobrych słów o mamie – rozmowa w kręgu",
      "opis": "Dzieci siedzą w kręgu i podają sobie nawzajem motek kolorowej włóczki, tworząc wspólną sieć życzliwości. Każdy przedszkolak kończy zdanie: „Moja mama jest wspaniała, ponieważ...”. Nauczyciel czuwa nad płynnością wypowiedzi i zapisuje najciekawsze myśli dzieci na dużym kartonowym sercu, które ozdobi salę na cały tydzień."
    },
    {
      "tytul": "Taniec z kolorowymi szarfami – zabawa ruchowo-muzyczna",
      "opis": "Nauczyciel włącza pogodną, spokojną melodię i rozdaje każdemu dziecku barwną szarfę. Przedszkolaki poruszają się po sali, kreśląc w powietrzu kształty serduszek i fal w rytm muzyki. Na przerwę w dźwiękach dzieci zatrzymują się i zastygają w bezruchu z szerokim uśmiechem niczym postacie z pamiątkowej fotografii."
    },
    {
      "tytul": "Portret mojej mamy – praca plastyczna z elementami wyklejanki",
      "opis": "Dzieci rysują portret swojej mamy na sztywnych kartkach za pomocą grubych kredek świecowych lub pasteli olejnych. Nauczyciel przygotowuje pociętą kolorową włóczkę, z której dzieci naklejają fryzury dopasowane do koloru włosów swoich mam. Gotowe rysunki zostają wyeksponowane w przedszkolnej galerii dla rodziców."
    }
  ]
}
